package net.officefloor.hq.app.rate;

import java.sql.Date;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The stored rates, one per grade and from-date per sheet. A grade with no row has no rate. */
@Repository
public class RateRepository {

    private static final String COLUMNS = "sheet_id, grade, rate, from_date, to_date";

    private final JdbcTemplate jdbc;
    private final SheetRepository sheets;

    public RateRepository(JdbcTemplate jdbc, SheetRepository sheets) {
        this.jdbc = jdbc;
        this.sheets = sheets;
    }

    /** The sheet's rates, by grade, then from-date (one with none first). */
    public List<Rate> list(String sheetId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM rate WHERE sheet_id = ? ORDER BY grade, from_date NULLS FIRST",
                RateRepository::map, sheetId);
    }

    /** The grade's rate in force on a date — the latest from-date on or before it, a rate with none applying
     *  from the beginning of time — or null when no rate applies, or that rate's to-date is before the date. */
    public Rate find(String sheetId, String grade, LocalDate on) {
        List<Rate> found = jdbc.query("SELECT " + COLUMNS + " FROM rate WHERE sheet_id = ? AND grade = ?"
                + " AND (from_date IS NULL OR from_date <= ?) ORDER BY from_date DESC NULLS LAST LIMIT 1",
                RateRepository::map, sheetId, grade, Date.valueOf(on));
        if (found.isEmpty() || (found.get(0).to() != null && found.get(0).to().isBefore(on))) {
            return null;
        }
        return found.get(0);
    }

    /** Every rate stored on the sheet while its today was on or before the date, in the order stored. */
    public List<Rate> storedBy(String sheetId, LocalDate madeOn) {
        return jdbc.query("SELECT " + COLUMNS + " FROM rate_log WHERE sheet_id = ? AND made_on <= ? ORDER BY id",
                RateRepository::map, sheetId, Date.valueOf(madeOn));
    }

    /** Stores the rate, replacing the one the grade had for the same from-date, and logs it with the sheet's today. */
    public Rate save(Rate rate) {
        Date from = rate.from() == null ? null : Date.valueOf(rate.from());
        jdbc.update("DELETE FROM rate WHERE sheet_id = ? AND grade = ? AND from_date IS NOT DISTINCT FROM ?",
                rate.sheetId(), rate.grade(), from);
        jdbc.update("INSERT INTO rate (" + COLUMNS + ") VALUES (?, ?, ?, ?, ?)",
                rate.sheetId(), rate.grade(), rate.rate(), from, rate.to() == null ? null : Date.valueOf(rate.to()));
        jdbc.update("INSERT INTO rate_log (" + COLUMNS + ", made_on) VALUES (?, ?, ?, ?, ?, ?)",
                rate.sheetId(), rate.grade(), rate.rate(), from, rate.to() == null ? null : Date.valueOf(rate.to()),
                Date.valueOf(sheets.today(rate.sheetId())));
        return rate;
    }

    private static Rate map(ResultSet rs, int n) throws SQLException {
        Date from = rs.getDate("from_date");
        Date to = rs.getDate("to_date");
        return new Rate(rs.getString("sheet_id"), rs.getString("grade"), rs.getBigDecimal("rate").setScale(2),
                from == null ? null : from.toLocalDate(), to == null ? null : to.toLocalDate());
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The stored sheets. A sheet never changed has no row and reads as starting on the real date. */
@Repository
public class SheetRepository {

    private final JdbcTemplate jdbc;

    public SheetRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public Sheet find(String id) {
        return new Sheet(id, today(id), archived(id));
    }

    /** The sheet as it stood at the end of the date: the date stands in for its today, and it is archived only when it
     *  was archived while its today was on or before it. */
    public Sheet find(String id, LocalDate asOf) {
        if (asOf == null) {
            return find(id);
        }
        List<LocalDate> archivedOn = jdbc.query("SELECT archived_on FROM sheet_archived WHERE sheet_id = ?",
                (rs, n) -> rs.getObject(1, LocalDate.class), id);
        return new Sheet(id, asOf, !archivedOn.isEmpty() && AsOf.counts(archivedOn.get(0), asOf));
    }

    /**
     * The sheet's today. Use this — never {@code LocalDate.now()} — for every decision or default
     * that depends on the date.
     */
    public LocalDate today(String id) {
        List<LocalDate> found = jdbc.query("SELECT today FROM sheet WHERE id = ?",
                (rs, n) -> rs.getObject(1, LocalDate.class), id);
        return found.isEmpty() ? LocalDate.now() : found.get(0);
    }

    /** Whether a steward archived the sheet: an archived sheet refuses every change. */
    public boolean archived(String id) {
        Integer found = jdbc.queryForObject("SELECT COUNT(*) FROM sheet_archived WHERE sheet_id = ?", Integer.class, id);
        return found != null && found > 0;
    }

    /** Archives the sheet; false when it was already archived. */
    public boolean archive(String id, String by) {
        if (archived(id)) {
            return false;
        }
        jdbc.update("INSERT INTO sheet_archived (sheet_id, archived_by, archived_on) VALUES (?, ?, ?)", id, by, today(id));
        return true;
    }

    public void saveToday(String id, LocalDate today) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) VALUES (?, ?)", id, today);
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;

/**
 * A sheet: everything else in the app is kept per sheet, keyed by its id. {@code today} is the
 * sheet's own date — every date decision and default date on the sheet uses it, never the clock.
 * An {@code archived} sheet stays visible and refuses every change.
 */
public record Sheet(String id, LocalDate today, boolean archived) {
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Loads a sheet by id. A sheet that was never used starts empty, so every id loads. Read as of a date (see AsOf), it
 *  is the sheet as it stood then. */
public class LoadSheet {
    public void load(@PathVariable("sheetId") String sheetId,
            @RequestParam(value = "asOf", required = false) String asOf, SheetRepository sheets, Out<Sheet> sheet) {
        sheet.set(sheets.find(sheetId.trim(), AsOf.parse(asOf)));
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithSheet {
    public void respond(@Val Sheet sheet, ObjectResponse<Sheet> response) {
        response.send(sheet);
    }
}

