// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

/** The date this screen shows the sheet as of (yyyy-MM-dd; the `asof` search param, see features/asof), or ''. While
 *  set, every read of a sheet asks for it as it stood then (`asOf`), and every change carries it (the X-As-Of header)
 *  so the server refuses it. */
export function viewAsOf(): string {
  const raw = new URLSearchParams(window.location.search).get('asof') ?? '';
  return /^"?(\d{4}-\d{2}-\d{2})"?$/.exec(raw)?.[1] ?? '';
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const asOf = viewAsOf();
  if (asOf !== '' && path.startsWith('/api/sheets/')) {
    if ((init?.method ?? 'GET') === 'GET') {
      path = `${path}${path.includes('?') ? '&' : '?'}asOf=${asOf}`;
    } else {
      init = { ...init, headers: { ...(init?.headers as Record<string, string>), 'X-As-Of': asOf } };
    }
  }
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson, putJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPage } from '../../slots/defs/sheetPage';
import { useSheet, type Sheet } from '../session/session';

/** The sheet's today: shown, and changeable. Changing it re-reads the whole sheet. Also whether the sheet is
 *  archived, and archiving it (a steward only). Both share the sheet's one error element. */
function SheetToday({ sheetId, user }: { sheetId: string; user: string }) {
  const sheet = useSheet(sheetId);
  const queryClient = useQueryClient();
  const [typed, setTyped] = useState('');
  const submit = useSubmitOnce();
  const stored = (saved: Sheet) => {
    queryClient.setQueryData(['sheet', sheetId], saved);
    void queryClient.invalidateQueries({ queryKey: ['sheet', sheetId] });
  };
  const save = useMutation({
    mutationFn: (today: string) =>
      putJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}/today`, { today, by: user }),
    onSuccess: stored,
    onSettled: submit.end,
  });
  const archive = useMutation({
    mutationFn: () => postJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}/archive`, { by: user }),
    onSuccess: stored,
  });
  return (
    <form
      data-testid="sheet-today-form"
      onSubmit={(e) => {
        e.preventDefault();
        if (!submit.begin()) return;
        archive.reset();
        save.mutate(typed.trim());
      }}
    >
      Today <span data-testid="sheet-today">{sheet.data?.today}</span>{' '}
      <input
        type="date"
        data-testid="sheet-today-input"
        value={typed}
        onChange={(e) => {
          setTyped(e.target.value);
          save.reset();
          archive.reset();
        }}
      />
      <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
        Set today
      </button>{' '}
      Archived <span data-testid="sheet-archived">{sheet.data?.archived ? 'yes' : 'no'}</span>{' '}
      <button
        type="button"
        data-testid="sheet-archive"
        disabled={archive.isPending}
        onClick={() => {
          save.reset();
          archive.reset();
          archive.mutate();
        }}
      >
        Archive
      </button>
      {(save.isError || archive.isError) && (
        <span data-testid="sheet-error">
          {archive.isError ? 'Could not archive the sheet.' : 'Could not change today.'}
        </span>
      )}
import { QueryClient } from '@tanstack/react-query';

// Server data is NEVER copied into component state. A feature reads it with useQuery under its own
// key (e.g. ['clients'] / ['project', id, 'notes']) and changes it with useMutation +
// invalidateQueries. Two features share data by sharing a KEY, never by a parent holding it.
// retry:false + no focus refetching keep the e2e runs deterministic.
export const queryClient = new QueryClient({
  defaultOptions: {
    queries: { retry: false, refetchOnWindowFocus: false },
    mutations: { retry: false },
  },
});

